command:
C:\Windows\System32\WindowsPowerShell\v1.0\powershell.exe -NoProfile -Command '& {
$nodes=(Invoke-RestMethod -Uri "http://127.0.0.1:3080/v3/projects/CampusNetwork_04/nodes").name
function Get-Cfg($p,$n) {
  foreach($cmd in @("display current-configuration","show running-config")) {
    $e=[uri]::EscapeDataString($cmd)
    try {$o=(Invoke-RestMethod -Uri "http://127.0.0.1:3080/v3/projects/$p/nodes/$n/command?cmd=$e").output} catch {continue}
    if($o -and $o -notlike "Error:*not found*") {return $o}
  }
  return $null
}
$pat="(?i)(sysname|hostname|interface|ip address|ipv4 address|vlan|stp|spanning-tree|ospf|isis|bgp|peer|neighbor|route|prefix|cost|track|shutdown|nat|policy|acl|access-list|vpn|mpls|mtu|arp|binding|allow-pass|edge|bpdu|hrp|vrrp|vxlan|l2vpn|l3vpn|srv6|segment-routing|mac-address)"
foreach($n in $nodes) {
  $c=Get-Cfg "CampusNetwork_04" $n
  $b=Get-Cfg "CampusNetwork-for-perf_04" $n
  if(-not $c -or -not $b) {continue}
  $cl=@($c -split "\r?\n" | ForEach-Object {$_.TrimEnd()} | Where-Object {$_ -match $pat})
  $bl=@($b -split "\r?\n" | ForEach-Object {$_.TrimEnd()} | Where-Object {$_ -match $pat})
  $d=Compare-Object -ReferenceObject $bl -DifferenceObject $cl
  if($d) {
    Write-Output "===== $n ====="
    $d | ForEach-Object {"$($_.SideIndicator) $($_.InputObject)"}
  }
}
}'
